/* symm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "symm.h"

/* Tunable blocking factor for the j (column) dimension.
   This is a purely performance-oriented parameter and does not affect
   the numerical result.  It can be adjusted to better fit the cache
   hierarchy of a particular machine. */
#ifndef SYMM_J_BLOCK_SIZE
# define SYMM_J_BLOCK_SIZE 64
#endif


/* Array initialization. */
static
void init_array(int m, int n,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
      B[i][j] = (DATA_TYPE) ((n+i-j) % 100) / m;
    }
  for (i = 0; i < m; i++) {
    for (j = 0; j <=i; j++)
      A[i][j] = (DATA_TYPE) ((i+j) % 100) / m;
    for (j = i+1; j < m; j++)
      A[i][j] = -999; //regions of arrays that should not be used
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version notes
   -----------------------
   The original kernel used the loop order (i, j, k). In that form,
   the innermost loop iterated over k while accessing C[k][j] and B[k][j],
   which leads to strided accesses in the row-major layout and poor
   cache utilization.

   This optimized implementation reformulates the computation to use
   an (i, k, j) loop order and accumulates the intermediate "temp2"
   values in a temporary vector of length N for each i:

     temp2[j] = sum_{k < i} B[k][j] * A[i][k]

   For fixed i and k, the innermost loop now walks j over contiguous
   memory in rows of C and B, which significantly improves spatial
   locality and enables more effective vectorization.

   The mathematical operation is unchanged:
     C := alpha * A * B + beta * C
   with A symmetric (lower triangular region is used here), SIDE='L',
   UPLO='L', and the same per-element formula as the original code.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Temporary accumulation buffer for one row i:
     temp2[j] = sum_{k < i} B[k][j] * A[i][k].
     Using a whole row buffer avoids the scalar temp2 that was
     reinitialized for every (i, j) in the original code, while still
     performing the same total amount of work. */
  DATA_TYPE temp2[_PB_N];

  /* BLAS PARAMS
     SIDE = 'L'
     UPLO = 'L'
     =>  Form  C := alpha*A*B + beta*C
     A is MxM
     B is MxN
     C is MxN
     note that due to Fortran array layout, the code below more closely
     resembles upper triangular case in BLAS
  */
#pragma scop
  for (i = 0; i < _PB_M; i++)
  {
    /* Initialize accumulation buffer for this i.
       This corresponds to setting the original scalar temp2 = 0 for
       every column j, but does it using a vector to improve locality. */
    for (j = 0; j < _PB_N; j++)
      temp2[j] = (DATA_TYPE)0;

    /* For this fixed i, perform a rank-1 style update on the leading
       i x N block of C and accumulate temp2[j] at the same time.

       Original formulation (per i,j,k):
         C[k][j] += alpha * B[i][j] * A[i][k];
         temp2_ij += B[k][j] * A[i][k];

       New formulation (per i,k,j):
         - C[k][j] receives the same contributions, but now in
           contiguous j-order for each row k.
         - temp2[j] accumulates the same sum over k for each column j. */
    for (k = 0; k < i; k++)
    {
      DATA_TYPE a_ik = A[i][k];

      /* Row pointers help the compiler recognize linear accesses and
         vectorize the innermost loops.  The 'restrict' qualifier
         expresses the non-aliasing property of the PolyBench arrays. */
      DATA_TYPE *restrict Ck = C[k];
      DATA_TYPE *restrict Bi = B[i];
      DATA_TYPE *restrict Bk = B[k];

      /* j-tiling to improve cache locality when N is large. */
      for (int jj = 0; jj < _PB_N; jj += SYMM_J_BLOCK_SIZE)
      {
        int j_end = jj + SYMM_J_BLOCK_SIZE;
        if (j_end > _PB_N)
          j_end = _PB_N;

        /* No loop-carried dependencies across j, so it is safe to
           tell the compiler it may vectorize aggressively. */
        #pragma GCC ivdep
        for (j = jj; j < j_end; j++)
        {
          /* Same arithmetic as the original:
               C[k][j] += alpha * B[i][j] * A[i][k];
               temp2[j] += B[k][j] * A[i][k]; */
          Ck[j] += alpha * Bi[j] * a_ik;
          temp2[j] += Bk[j] * a_ik;
        }
      }
    }

    /* Finalize row i of C:
       Original:
         C[i][j] = beta * C[i][j]
                   + alpha * B[i][j] * A[i][i]
                   + alpha * temp2_ij;

       Here temp2[j] holds temp2_ij after the k-loop above. */
    DATA_TYPE *restrict Ci = C[i];
    DATA_TYPE *restrict Bi = B[i];
    DATA_TYPE a_ii = A[i][i];

    #pragma GCC ivdep
    for (j = 0; j < _PB_N; j++)
    {
      Ci[j] = beta * Ci[j]
            + alpha * Bi[j] * a_ii
            + alpha * temp2[j];
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,M,N,m,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,M,M,m,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,M,N,m,n);

  /* Initialize array(s). */
  init_array (m, n, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_symm (m, n,
	       alpha, beta,
	       POLYBENCH_ARRAY(C),
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(m, n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
}
