static
void print_array(int m, int n,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < m; i++)
    for (j = 0; j < n; j++) {
	if ((i * m + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version notes:
   ------------------------
   - We first scale C by beta once, instead of doing it inside the
     main loop. In the original kernel each row i of C is untouched
     before being written for the first time, so this transformation
     is mathematically equivalent.
   - We then reformulate the symmetric matrix-matrix multiply using
     explicit symmetric rank-2 style updates:
         For each i, for each k<i, and for all j:
           C[k][j] += alpha * A[i][k] * B[i][j];
           C[i][j] += alpha * A[i][k] * B[k][j];
       plus the diagonal term:
           C[i][j] += alpha * A[i][i] * B[i][j];
     This is algebraically identical to the original algorithm.
   - Loops are reordered so that the innermost loop is over j
     (columns). Since the arrays are stored in row-major order, this
     yields unit-stride accesses in B and C for the innermost loop,
     substantially improving cache locality and vectorization.
   - We introduce restricted pointers to A, B, and C to help the
     compiler with alias analysis.
   - A tunable blocking factor SYMM_J_BLOCK is used on the j loop
     in the hot path to improve cache reuse for large N.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Create local restricted views of the arrays.  Using 'restrict'
     tells the compiler that A_, B_, and C_ do not alias each other,
     which enables better optimization and vectorization.  The second
     dimension uses the runtime sizes m and n so that this remains
     valid even when problem sizes change. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE (* restrict B_)[n] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

#pragma scop
  /* 1. Scale C by beta once.
     In the original kernel, each element C[i][j] is multiplied by
     beta exactly once, at the first (and only) assignment to that
     element in the (i,j) loops.  No prior updates touch C[i][j],
     so performing this scaling up front is equivalent. */
  for (i = 0; i < _PB_M; i++)
    for (j = 0; j < _PB_N; j++)
      C_[i][j] *= beta_;

  /* 2. Symmetric matrix-matrix multiply using only the lower
        triangular part of A.

     Final mathematical form for each element is:
       C[r][j] = beta*C0[r][j]
                 + alpha*B[r][j]*A[r][r]
                 + alpha*sum_{k<r} B[k][j]*A[r][k]
                 + alpha*sum_{i>r} B[i][j]*A[i][r];

     The loop nest below implements exactly this formula using
     symmetric rank-2 updates, while accessing B and C with
     contiguous (unit-stride) memory in the innermost loop. */
  for (i = 0; i < _PB_M; i++)
  {
    /* Diagonal contribution for row i: alpha * A[i][i] * B[i][:] */
    const DATA_TYPE aii = alpha_ * A_[i][i];

    for (j = 0; j < _PB_N; j++)
      C_[i][j] += aii * B_[i][j];

    /* Off-diagonal symmetric updates for all k < i:
         For each pair (i, k) with k < i and for all columns j:
           C[k][j] += alpha * A[i][k] * B[i][j];
           C[i][j] += alpha * A[i][k] * B[k][j];
       This matches the effect of the original triple loop that
