           compiler that it can safely vectorize. */
        #pragma GCC ivdep
        for (j = jj; j < j_end; j++)
        {
          C_[k][j] += B_[i][j] * aik;
          C_[i][j] += B_[k][j] * aik;
        }
      }
    }
  }
#pragma endscop
}


