   - Loop reordering to make the column (j) dimension the innermost
     loop for the updates on B and C, which improves spatial locality
     and enables better vectorization.

   - Use of a temporary buffer temp2[] to maintain the original
     arithmetic order of the inner reduction:
         temp2(j) = sum_{k < i} B[k][j] * A[i][k]
     while allowing the (i, k, j) loop ordering.

   - Pre-scaling of C by beta outside the main kernel.  In the original
     algorithm each C[i][j] is multiplied by beta exactly once when
     i == row index.  Scaling once up-front is mathematically and
     numerically equivalent, but removes the beta multiplication from
     the hot loop.

   - Introduction of restricted pointers and per-row pointers (Bi, Bk,
     Ci, Ck) to help the compiler generate efficient code.

   - Blocking in the N (column) dimension using SYMM_BLOCK_SIZE_N to
     keep the temp2 buffer small and to improve cache behavior for
     large N.

   The resulting computation is exactly equivalent to the original
   one in terms of floating-point operation order per element.
*/
static
void kernel_symm[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Effective iteration bounds (may be smaller than m,n if PolyBench
     is configured to run "mini" problem sizes). */
  const int m_eff = _PB_M;
  const int n_eff = _PB_N;

  /* Create local restricted pointers to help the optimizer.
     The PolyBench harness allocates A, B, and C in disjoint regions,
     so assuming non-aliasing between them is valid for this benchmark. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[n] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /* 1) Scale C by beta once.
     In the original code each element C[i][j] is multiplied by beta
     exactly once, when the outer index i equals the row index.
     Performing this scaling up-front is therefore strictly equivalent
     (same operations, same order of updates per C[i][j]). */
  if (beta_ != (DATA_TYPE)1.0)
  {
    for (i = 0; i < m_eff; ++i)
    {
      DATA_TYPE *restrict Ci = C_[i];
      for (j = 0; j < n_eff; ++j)
        Ci[j] *= beta_;
    }
  }

  /* Temporary accumulation buffer for a block of columns in the N
     dimension.  For each i and column j in the current block:
         temp2(block-local j) =
             sum_{k=0}^{i-1} B[k][j_global] * A[i][k]
     This matches the original definition of temp2 for each (i,j). */
  DATA_TYPE temp2[SYMM_BLOCK_SIZE_N];

#pragma scop
  for (i = 0; i < m_eff; ++i)
  {
    DATA_TYPE *restrict Bi = B_[i];
    DATA_TYPE *restrict Ci = C_[i];
    const DATA_TYPE Aii = A_[i][i];
    const DATA_TYPE alphaAii = alpha_ * Aii;

    /* Process columns in blocks to limit the working set and to keep
       temp2 small (stays in L1/L2). */
    for (int jj = 0; jj < n_eff; jj += SYMM_BLOCK_SIZE_N)
    {
      const int jb = (jj + SYMM_BLOCK_SIZE_N <= n_eff)
                     ? SYMM_BLOCK_SIZE_N
                     : (n_eff - jj);

      /* Initialize temp2 for this block of columns. */
      for (j = 0; j < jb; ++j)
        temp2[j] = (DATA_TYPE)0;

      /* Accumulate contributions for k < i.

         Original inner loops (simplified):

           for (j)
             temp2 = 0;
             for (k < i) {
               C[k][j] += alpha * B[i][j] * A[i][k];
               temp2   +=        B[k][j] * A[i][k];
             }
             C[i][j] = beta*C[i][j] + alpha*B[i][j]*A[i][i]
                                     + alpha*temp2;

         Here we use loop order (i, k, j) within a column block but
         maintain, for each fixed (i,j), the same order of k in the
         temp2 reduction (k increases from 0 to i-1).  Each update
         to a given C[k][j] still occurs exactly once per (i,k,j)
         triple, so the per-element operation order is preserved. */
      for (k = 0; k < i; ++k)
      {
        const DATA_TYPE aik = A_[i][k];
        DATA_TYPE *restrict Bk = B_[k];
        DATA_TYPE *restrict Ck = C_[k];

        for (j = 0; j < jb; ++j)
        {
          const int col = jj + j;
          const DATA_TYPE bij = Bi[col];
          const DATA_TYPE bkj = Bk[col];

          /* C[k][col] += alpha * B[i][col] * A[i][k]; */
          Ck[col] += alpha_ * bij * aik;

          /* temp2(col) += B[k][col] * A[i][k];   (stored block-local) */
          temp2[j] += bkj * aik;
        }
      }

      /* Finish the update of row i for this block of columns:

           C[i][col] += alpha * B[i][col] * A[i][i] + alpha * temp2(col);

         The initial beta scaling of C has been performed once before
         entering the main loop. */
      for (j = 0; j < jb; ++j)
      {
        const int col = jj + j;
        Ci[col] += alphaAii * Bi[col] + alpha_ * temp2[j];
      }
    } /* end block over jj */
  }   /* end loop over i */
#pragma endscop
}


