void kernel_symm [[gnu::flatten, gnu::noinline]] (int m, int n,
		 DATA_TYPE alpha,
		 DATA_TYPE beta,
		 DATA_TYPE POLYBENCH_2D(C,M,N,m,n),
		 DATA_TYPE POLYBENCH_2D(A,M,M,m,m),
		 DATA_TYPE POLYBENCH_2D(B,M,N,m,n))
{
  int i, j, k;

  /* Make local const copies so the compiler can keep them in registers. */
  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

#pragma scop

  /* 1) Pre-scale C by beta.
     This preserves the original semantics, where each C[i][j] was
     multiplied by beta exactly once, when i reached that row. */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE * __restrict Ci = C[i];
    for (j = 0; j < _PB_N; j++)
    {
      Ci[j] *= beta_local;
    }
  }

  /* 2) Compute C := C + alpha * A * B using the lower triangle of A.

     For each i:
       - First add the diagonal contribution A[i][i] * B[i,:] to row i.
       - Then for each k<i, use A[i][k] to update rows k and i:

           C[k,:] += alpha * A[i][k] * B[i,:]
           C[i,:] += alpha * A[i][k] * B[k,:]

     All inner loops run over j (columns), so B and C are accessed
     contiguously in memory, improving cache locality and enabling
     effective SIMD vectorization.
