    DATA_TYPE * __restrict Bi = B[i];
    DATA_TYPE * __restrict Ci = C[i];

    /* Diagonal contribution for row i: alpha * A[i][i] * B[i,:] */
    DATA_TYPE alphaAii = alpha_local * Ai[i];

    /* Row i update: C[i,:] += alpha * A[i][i] * B[i,:] */
    for (j = 0; j < _PB_N; j++)
    {
      Ci[j] += alphaAii * Bi[j];
    }

    /* Off-diagonal symmetric updates. */
    for (k = 0; k < i; k++)
    {
      DATA_TYPE * __restrict Bk = B[k];
      DATA_TYPE * __restrict Ck = C[k];

      /* This factor is reused across all columns j. */
      DATA_TYPE alphaAik = alpha_local * Ai[k];

      /* For each column j:
           C[k][j] += alpha * A[i][k] * B[i][j]
           C[i][j] += alpha * A[i][k] * B[k][j]
         All accesses are to contiguous elements in each row. */
      for (j = 0; j < _PB_N; j++)
      {
        DATA_TYPE Bij = Bi[j];
        DATA_TYPE Bkj = Bk[j];

        Ck[j] += alphaAik * Bij;
        Ci[j] += alphaAik * Bkj;
      }
    }
  }

